# Illustrative check: heat produced proportional to mu (same N, same distance)
N = 20.0   # normal force between palms, ~20 N (illustrative)
d = 1.0    # total sliding distance in one rubbing session, 1 m (illustrative)
mu = {"dry palms": 1.0, "wet palms": 0.4, "oil": 0.15, "lotion": 0.15}
for k, m in mu.items():
    print(f"{k:12s} mu={m:4.2f}  Q = mu*N*d = {m*N*d:6.2f} J")
best = max(mu, key=mu.get)
print("Most heat:", best)
"}

